+            }
+        }
+    }
+    auto empty = make_brute_force_backend(1);
+    REQUIRE(empty);
+    auto links = build_graph_topology(**empty, 2, 2);
+    REQUIRE(links);
+    REQUIRE(links->empty());
+}
